// Lambda (C++14):
auto betweenL = [low, high](auto val) { return low <= val && val <= high; };

// std::bind equivalent (C++11):
auto betweenB = std::bind(std::logical_and<bool>(),
                          std::bind(std::less_equal<int>(), low, _1),
                          std::bind(std::less_equal<int>(), _1, high));
